<?php declare(strict_types=1); ?><!doctype html><html lang="<?= e(\App\Core\Translator::locale()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Villa amenities</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:950px;margin:35px auto;padding:0 18px}.panel{background:white;padding:22px;border-radius:14px;margin:15px 0}input{padding:10px;border:1px solid #dfe6e0;border-radius:8px;margin:5px;font:inherit}button{background:#176b50;color:white;border:0;padding:10px 14px;border-radius:8px;font-weight:700}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #edf0ed}
