</style></head><body><main class="wrap"><h1>Villa amenities</h1><section class="panel"><form method="post" action="/admin/amenities/save"><?= csrf_field() ?><input name="name" placeholder="Amenity name" required><input name="icon" placeholder="Lucide icon name"><input name="sort_order" type="number" value="10" style="width:80px"><button>Add</button></form></section><section class="panel"><table><thead><tr><th>Amenity</th><th>Icon</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($amenities as $amenity): ?><tr><td><?= e($amenity['name']) ?></td><td><?= e($amenity['icon']) ?></td><td><?= (int)$amenity['is_active']?'Active':'Inactive' ?></td><td><form method="post" action="/admin/amenities/delete"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$amenity['id'] ?>"><button style="background:#a43">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></section></main></body></html>